  "확인 중…": "Comprobando…",
  "추가": "Añadir",
  "연결 시작 실패. Supabase 프로젝트에서 이 로그인 방식과 계정 연결(manual linking) 활성화 확인 필요": "No se pudo iniciar la vinculación. Comprueba que este método de inicio de sesión y la vinculación manual de cuentas estén activados en el proyecto de Supabase",
  "마지막 로그인 수단은 연결 해제 불가": "No puedes desvincular tu último método de inicio de sesión",
  "연결 해제 실패": "No se pudo desvincular",
  "복사됨": "Copiado",
  "복사": "Copiar",
  "로그인 수단": "Métodos de inicio de sesión",
  "이메일·비밀번호": "Correo y contraseña",
  "연결 해제": "Desvincular",
  "연결하기": "Vincular",
  "어떤 수단으로 로그인해도 같은 계정으로 연결. 다른 기기·로그인 방식을 함께 쓰려면 미리 연결": "Cualquier método vinculado inicia sesión en la misma cuenta. Vincula métodos con antelación para usar otros dispositivos o formas de acceso",
  "계정 탈퇴": "Eliminar cuenta",
  "확인을 위해 \"{0}\" 입력": "Para confirmar, escribe «{0}»",
  "백의 첫 수. e4는 개방적·공격적, d4는 전략적·폐쇄적": "Primera jugada de las blancas. e4 es abierta y agresiva; d4, estratégica y cerrada",
  "이탈리안 게임의 갈림길. 흑 …Bc5(지우코 피아노, 조용한 전략전) 또는 …Nf6(투 나이츠, 날카로운 전술전). 채택률 비슷": "La encrucijada de la Partida Italiana. Las negras juegan …Bc5 (Giuoco Piano, lucha estratégica tranquila) o …Nf6 (Defensa de los Dos Caballos, lucha táctica aguda). Ambas se juegan casi por igual",
  "4.Ng5는 f7 직접 위협. 평가를 지키는 수는 사실상 4...d5뿐": "4.Ng5 amenaza f7 directamente. En la práctica, 4...d5 es la única jugada que mantiene la evaluación",
  "트랙슬러 카운터어택. f7을 내주고 f2를 맞받는 함정 수": "El contraataque Traxler. Una jugada trampa que cede f7 y contraataca f2",
  "백의 첫 수. 게임 전체 성격(개방/폐쇄, 전술/전략)을 정하는 최상위 분기": "Primera jugada de las blancas. La bifurcación principal que define el carácter de toda la partida (abierta o cerrada, táctica o estratégica)",
  "흑의 선택지: 1...e5(오픈 게임), c5(시칠리안), e6(프렌치), c6(카로칸)": "Opciones de las negras: 1...e5 (Juego Abierto), c5 (Siciliana), e6 (Francesa), c6 (Caro-Kann)",
  "흑 e5 방어: 2...Nc6(정통), Nf6(페트로프), d6(필리도르)": "Defensa de e5 de las negras: 2...Nc6 (clásica), Nf6 (Petrov), d6 (Philidor)",
  "백의 공격 플랜: 3.Bb5(루이 로페즈, 구조적 압박) vs 3.Bc4(이탈리안, 빠른 f7 공략)": "Plan de ataque de las blancas: 3.Bb5 (Apertura Española, presión estructural) frente a 3.Bc4 (Italiana, ataque rápido a f7)",
  "이탈리안의 성격: 3...Bc5(지우코 피아노, 전략전) vs 3...Nf6(투 나이츠, 전술전)": "Carácter de la Italiana: 3...Bc5 (Giuoco Piano, estratégica) frente a 3...Nf6 (Dos Caballos, táctica)",
  "프라이드 리버: f7 위협에 4...d5만 사실상 유일한 정수": "Hígado Frito: ante la amenaza sobre f7, 4...d5 es prácticamente la única jugada correcta",
  "루이 로페즈 핵심: 3...a6(모펀 메인) vs 3...Nf6(베를린 디펜스)": "Clave de la Apertura Española: 3...a6 (línea principal Morphy) frente a 3...Nf6 (Defensa Berlinesa)",
  "안티-시칠리안: 2.Nf3(오픈 시칠리안) vs 2.Nc3 / c3 / Bc4(폐쇄·알라핀 등)": "Anti-Siciliana: 2.Nf3 (Siciliana Abierta) frente a 2.Nc3 / c3 / Bc4 (variantes cerradas, Alapin, etc.)",
  "오픈 시칠리안: 2...d6(나이도르프/드래곤), Nc6(스벤니/클래식), e6(타이마노프/카안)": "Siciliana Abierta: 2...d6 (Najdorf/Dragón), Nc6 (Sveshnikov/Clásica), e6 (Taimanov/Kan)",
  "프렌치 구조: 3.Nc3, Nd2(타라쉬), e5(어드밴스), exd5(익스체인지)로 폰 구조가 갈림": "Estructuras de la Francesa: la estructura de peones se bifurca con 3.Nc3, Nd2 (Tarrasch), e5 (Avance), exd5 (Cambio)",
  "카로칸 구조: 3.Nc3/Nd2(클래시컬), e5(어드밴스), exd5(익스체인지), f3(핀란드)": "Estructuras de la Caro-Kann: 3.Nc3/Nd2 (Clásica), e5 (Avance), exd5 (Cambio), f3 (Finlandesa)",
  "흑의 응수: 1...d5(정통 폐쇄) vs 1...Nf6(인디언, 초현대적 중앙 양보)": "Respuesta de las negras: 1...d5 (clásica, cerrada) frente a 1...Nf6 (India, hipermoderna: cede el centro)",
  "퀸스 갬빗: 2...e6(QGD), c6(슬라브), dxc4(QGA)": "Gambito de dama: 2...e6 (QGD), c6 (Eslava), dxc4 (QGA)",
  "인디언 디펜스: 2...e6(님조/QID), g6(KID/그륀펠트), c5(베노니)": "Defensas Indias: 2...e6 (Nimzo/QID), g6 (KID/Grünfeld), c5 (Benoni)",
  "3...Bb4(님조-인디언, 핀) vs 3...d5(QGD 전환)": "3...Bb4 (India de Nimzowitsch, una clavada) frente a 3...d5 (transposición a la QGD)",
  "3...d5(그륀펠트, 중앙 반격) vs 3...Bg7→d6(킹스 인디언, 폐쇄 공격)": "3...d5 (Grünfeld, contraataque en el centro) frente a 3...Bg7→d6 (India de Rey, ataque cerrado)",
  "다미아노 디펜스 응징의 핵심. 4.Qh5+ 더블 어택으로 e5 폰 회수, 흑 킹 노출": "La clave para castigar la Defensa Damiano. 4.Qh5+ es un doble ataque que recupera el peón de e5 y deja expuesto al rey negro",
  "폰지아니 오프닝. d4를 준비하며 중앙을 노리는 고전 정석": "La Apertura Ponziani. Una línea clásica que prepara d4 y apunta al centro",
  "스칸디나비안 디펜스. 흑이 d5로 중앙을 바로 교환해 빠르게 전개. 백은 2.exd5 뒤 퀸/나이트 회수 라인으로 분기": "La Defensa Escandinava. Las negras cambian el centro de inmediato con d5 y desarrollan rápido. Tras 2.exd5, las blancas se bifurcan en líneas que recuperan con la dama o con el caballo",
  "이미지를 읽지 못함": "No se pudo leer la imagen",
  "네트워크 오류로 이미지 인식 실패": "Error en el reconocimiento de la imagen por un problema de red",
  "기물을 희생하면서도 포지션을 유리하게 이끄는, 찾기 어려운 최상의 수": "Una jugada excelente y difícil de encontrar que sacrifica material pero lleva la posición a tu favor",
  "두지 않으면 포지션이 크게 나빠지는, 사실상 유일하게 좋은 수": "Si no la juegas, la posición empeora mucho. Prácticamente la única jugada buena",
  "엔진이 계산한 그 포지션의 가장 좋은 수": "La mejor jugada de esa posición según el motor",
  "최선은 아니지만 평가치 손실이 거의 없는 훌륭한 수": "No es la mejor, pero es una jugada excelente con casi ninguna pérdida de evaluación",
  "무난하게 좋은 수. 포지션을 크게 해치지 않음": "Una buena jugada sólida. No perjudica mucho la posición",
  "더 나은 수가 있었던, 평가치 손실이 약간 있는 수": "Una jugada con una ligera pérdida de evaluación, existiendo una mejor",
  "상대 실수로 생긴 기회를 살리지 못한 수": "Una jugada que no aprovechó la oportunidad creada por el error del rival",
  "평가치를 눈에 띄게 떨어뜨려 불리해진 수": "Una jugada que reduce notablemente la evaluación y te deja en peor situación",
  "승패를 뒤집을 만큼 평가치를 크게 잃은 치명적인 실수": "Un error fatal que pierde tanta evaluación que puede cambiar el resultado",
