  "피크 레이팅": "Rating máximo",
  "/user 페이지 우상단 X 버튼을 점 3개 메뉴(신고·차단)로 교체했습니다. 좌상단에 @아이디 표시합니다.": "El botón X de la esquina superior derecha de la página /user se sustituyó por un menú de tres puntos (reportar/bloquear). El @ID aparece arriba a la izquierda.",
  "신고 사유를 체크박스로 중복 선택했습니다. 개발자 모드에서 신고자·신고 대상 아이디와 신고 내용(최근 대화 포함) 열람 추가했습니다.": "Los motivos del reporte se pueden elegir varios con casillas. En modo desarrollador se ven los IDs de quien reporta y del reportado, y el contenido (con la conversación reciente).",
  "채팅창 상단에 '최근 활동' 표시합니다. 신고·차단 버튼을 점 3개 메뉴로 통합했습니다.": "Se muestra 'Última actividad' bajo el ID en la parte superior del chat. Los botones de reportar y bloquear se unieron en un menú de tres puntos.",
  "채팅의 모든 요소(카드·알림 포함)에 반응 가능 추가했습니다. 더블클릭하면 하트 반응 추가했습니다. 반응 이모지를 말풍선에 붙여 표시합니다.": "Se puede reaccionar a todos los elementos del chat, incluidas tarjetas y avisos. Con doble clic se reacciona con un corazón. Las reacciones quedan pegadas a la burbuja.",
  "대국 신청 카드의 띄어쓰기 오류를 수정했습니다. '끝난 대국'을 '대국 종료됨'으로 표기합니다.": "Corregido un error de espaciado en las tarjetas de solicitud de partida. 'Partida finalizada' ahora dice 'Partida terminada'.",
  "미니게임 육각형 엠블럼에서 'MiniGame' 글자 삭제했습니다.": "Se quitó el texto 'MiniGame' del emblema hexagonal de minijuegos.",
  "신고 사유 (중복 선택 가능)": "Motivos del reporte (puedes elegir varios)",
  "신고한 메시지와 최근 대화는 검토를 위해 운영진에게 전달. 상대에게는 알리지 않음": "El mensaje denunciado y la conversación reciente se envían al equipo para su revisión. No se avisa al otro usuario",
  "신고 목록": "Reportes",
  "새로 고침": "Actualizar",
  "처리 대기": "Pendiente",
  "처리 완료": "Resuelto",
  "서버에 반영되지 않음. supabase-setup.sql 재실행 필요": "No aplicado en el servidor. Vuelve a ejecutar supabase-setup.sql",
  "불러오기 실패": "Error al cargar",
  "신고 없음": "Sin reportes",
  "프로필 신고": "Reporte de perfil",
  "신고된 메시지": "Mensaje denunciado",
  "대화 기록": "Historial del chat",
  "대국 종료됨": "Partida terminada",
  "대결 종료됨": "Duelo terminado",
  "최근 활동 : {0}": "Última actividad: {0}",
  "분석 탭 수 블록의 공개 데이터 통계가 '- / -'로 남거나 채택률 막대가 비던 문제를 수정했습니다. 통계 조회가 실패하면 자동으로 다시 시도 추가했습니다.": "Corregido: las estadísticas de datos públicos de los bloques de jugadas del análisis se quedaban en '— / —' o con la barra de adopción vacía. Si falla una consulta, se reintenta automáticamente.",
  "프로필의 통계 전환 버튼을 'OpenChess'·'외부 사이트' 글자로 변경했습니다.": "El selector de estadísticas del perfil ahora usa los textos 'OpenChess' y 'sitio externo'.",
  "미니게임 랭킹 화면의 중복된 '로비' 버튼 삭제했습니다.": "Eliminado el botón 'Lobby' redundante de la pantalla de clasificación de minijuegos.",
  "일반 대국 전적·레이팅·랭킹 추가했습니다. 랜덤 매칭 결과가 미니게임과 같은 형태의 랭킹에 반영했습니다.": "Añadidos historial, rating y clasificación para las partidas normales. Los resultados del emparejamiento aleatorio cuentan en una clasificación con el mismo formato que los minijuegos.",
  "나이트 레이스 이동 수 제한 삭제했습니다. 제한시간 안이면 몇 수든 이동 가능 추가했습니다.": "Eliminado el límite de jugadas en la Carrera del Caballo. Puedes hacer todas las que quieras dentro del tiempo límite.",
  "나이트 레이스 혼자 플레이에서 목표에 못 닿으면 정산 전에 최단 경로를 금색 화살표로 표시합니다.": "En la Carrera del Caballo en solitario, si no llegas a la casilla objetivo, el camino más corto se muestra con flechas doradas antes del resumen de la ronda.",
  "나이트 레이스 거리 판정 연출이 칸에서 어긋나던 문제를 수정했습니다.": "Corregida la animación del desempate por distancia de la Carrera del Caballo, que se desviaba de las casillas.",
  "무한 체크메이트 포지션을 수천 개로 확대했습니다. 백랭크·스머더드 등 다양한 체크메이트 모양을 고르게 출제하며, 한 번 나온 포지션은 모두 소진하기 전까지 다시 나오지 않습니다.": "Jaque mate infinito ahora tiene miles de posiciones. Aparecen por igual muchos patrones de jaque mate, como el mate de la última fila y el mate ahogado, y ninguna posición se repite hasta agotarlas todas.",
  "무한 체크메이트 대전에서 상대의 진행 상황(수순 탐색 중·정확한 수순·실패·체크메이트 성공) 표시합니다.": "En las partidas de jaque mate infinito se muestra el progreso del rival: buscando la secuencia, secuencia correcta, fallo o jaque mate conseguido.",
  "무한 체크메이트 동점 시 결과 화면 전에 등급별 성공 수를 하나씩 비교하는 정산 화면 추가했습니다.": "Si el jaque mate infinito termina en empate, una pantalla de desempate compara los éxitos por grado antes del resultado.",
  "일반 대국 랭킹, 나이트 레이스 개선, 무한 체크메이트 대폭 확장, 공개 데이터 통계 표시 수정했습니다.": "Clasificación de partidas normales, mejoras en la Carrera del Caballo, gran ampliación de Jaque mate infinito, corrección de estadísticas de datos públicos.",
  "일반 대국 랭킹, 나이트 레이스 최단 경로 화살표, 체크메이트 포지션 수천 개, 상대 진행 상황 표시합니다.": "Clasificación de partidas normales, flechas del camino más corto en la Carrera del Caballo, miles de posiciones de jaque mate, progreso del rival",
  "일반 대국 랭킹, 나이트 레이스 최단 경로 화살표, 체크메이트 포지션 수천 개, 상대 진행 상황 표시": "Clasificación de partidas normales, flechas del camino más corto en la Carrera del Caballo, miles de posiciones de jaque mate, progreso del rival",
