  "보드 스킨·기물 스킨 모음. 기본 스킨은 바로 장착, 상점에서 구매한 스킨도 여기서 장착·구매 가능. 미보유 스킨은 미리보기": "Colección de skins de tablero y de piezas. Las skins predeterminadas se equipan al instante; las compradas en la tienda también se pueden equipar o comprar aquí. Las skins que no tienes se muestran como vista previa",
  "체스보드 스킨": "Skins de tablero",
  "기물 스킨": "Skins de piezas",
  "칭호를 클릭하면 획득 조건 표시. 획득한 칭호는 클릭해 장착": "Haz clic en un título para ver cómo conseguirlo. Haz clic en uno obtenido para equiparlo",
  "퍼즐 {0}": "Puzles {0}",
  "체스컴 {0}": "chess.com {0}",
  "도감 해금률 {0}": "Aperturas desbloqueadas {0}",
  "퀸으로 승진하면 상대가 둘 수 있는 합법수가 없어져 스테일메이트로 무승부가 되므로, 대신 {0:을/를} 골라 승진하는 수입니다.": "Coronar en dama sería rey ahogado, tablas. En su lugar se corona en {0}",
  "퀸으로 승진하면 곧바로 잡히지만 {0:은/는} 안전하게 남을 수 있어, 대신 {0:을/를} 골라 승진하는 수입니다.": "Coronar en dama la perdería, la capturan de inmediato. Coronar en {0} es seguro",
  "퀸이 아닌 {0:을/를} 골라 승진하는, 흔치 않은 감각의 수입니다.": "Coronar en {0} en lugar de dama. Una elección poco habitual",
  "{0:과/와} {1:을/를} 교환하는 건 쉽지 않은 선택이지만, 지금 상황에선 탁월한 선택입니다.": "Cambiar {0} por {1}. No es fácil, pero es una elección brillante en esta situación",
  "{0:을/를} 그대로 걸어 둔 채 그 위협을 무시하고, 대신 더 큰 이득을 얻어내는 수입니다.": "Una jugada que ignora la amenaza sobre esta pieza, {0},  y gana algo mayor",
  "{0:을/를} 내주는 과감한 희생으로, 눈앞의 손해를 감수하고 더 큰 것을 노리는 수입니다.": "Sacrificio de {0}. Acepta una pérdida inmediata para buscar algo mayor",
  "눈에 보이는 손해를 감수하면서까지 더 큰 것을 노리는, 찾기 쉽지 않은 수입니다.": "Una jugada que acepta una pérdida visible para buscar algo mayor",
  "이미 불리하던 상황에서 그대로 두면 계속 밀릴 뿐이라, {0} 수순으로 {1:을/를} 만들어 무승부를 강제해야 했던 수입니다.": "Posición ya desfavorable. La línea {0} fuerza tablas por {1}",
  "참고로 엔진이 고른 최선의 수는 아니지만, 찾기 힘든 감각적이고 탁월한 수입니다.": " Aunque no es la Mejor jugada del motor, es una jugada Brillante, intuitiva y difícil de encontrar.",
  ": 탁월한 수": ": Jugada brillante",
  "기물을 내주는 위험을 감수했지만 정확히 계산된 최고의 수입니다.": "Una jugada excelente que arriesga material pero está calculada con exactitud",
  "찾기 어려운 수를 정확히 찾아냈습니다.": "Encontraste con precisión una jugada difícil",
  ": 최선의 수": ": Mejor jugada",
  "엔진이 찾은 이 포지션의 가장 좋은 수입니다.": "La mejor jugada de esta posición según el motor",
  "정확한 수입니다.": "Una jugada precisa",
  ": 유일한 수": ": Única jugada",
  "다른 수는 크게 불리하며, 반드시 이 수를 두어야 합니다.": "Cualquier otra jugada es mucho peor. Esta jugada es obligada",
  "이 수는 현재 포지션에서 유일한 수입니다.": "Es la Única jugada de la Posición actual.",
  ": 우수한 수": ": Jugada excelente",
  "최선은 아니지만 아주 좋은 선택입니다.": "No es la mejor, pero es una muy buena elección",
  "이 포지션에서 둘 만한 좋은 수 가운데 하나입니다.": "Una de las buenas jugadas de esta posición",
  ": 좋은 수": ": Buena jugada",
  "무난하고 안정적인 수입니다.": "Una jugada sólida y estable",
  "포지션을 잘 유지하는 수입니다.": "Una jugada que mantiene bien la posición",
  ": 이론 수": ": Jugada de teoría",
  "오래 검증된 정석 수입니다.": "Una jugada estándar probada durante mucho tiempo",
  "책에 나오는 잘 알려진 수입니다.": "Una jugada conocida de los libros",
  ": 부정확한 수": ": Imprecisión",
  "더 나은 수가 있습니다. 큰 손해는 아니지만 아쉬운 수입니다.": "Había una jugada mejor. No es una gran pérdida, pero es una lástima",
  "포지션이 약간 나빠졌습니다.": "La posición empeora un poco",
  ": 기회를 놓침": ", Oportunidad perdida",
  "상대의 실수를 응징할 기회를 활용하지 못했습니다.": "No aprovechaste la oportunidad de castigar el error del rival",
  "더 강한 수가 있었습니다.": "Había una jugada más fuerte",
