  "대국 리뷰 보기": "Ver revisión de partida",
  "공유 링크를 만드는 중…": "Creando el enlace para compartir…",
  "이미지 카드로 공유": "Compartir como tarjeta de imagen",
  "만드는 중…": "Creando…",
  "카드 준비 중…": "Preparando la tarjeta…",
  "이미지로 공유": "Compartir como imagen",
  "이미지 저장": "Guardar imagen",
  "백의 첫 수. e4·d4가 압도적. b4(폴란드)·f4(버드)처럼 평가가 떨어지는 수는 부정확으로 분류": "Primera jugada de las blancas. e4 y d4 dominan. Las jugadas que bajan la evaluación, como b4 (Polaca) y f4 (Bird), se clasifican como imprecisiones",
  "킹 폰 오프닝. 중앙 점유, 비숍·퀸 길을 열어 빠른 전개와 공격": "Apertura de peón de rey. Ocupa el centro y abre líneas para el alfil y la dama, con desarrollo y ataque rápidos",
  "퀸 폰 오프닝. e4보다 폐쇄적·전략적, 안정적인 중앙 장악": "Apertura de peón de dama. Más cerrada y estratégica que e4, con un control estable del centro",
  "이탈리안 게임. 비숍을 c4로 보내 f7 약점 공략. 흑 …Bc5(지우코 피아노) 또는 …Nf6(투 나이츠)": "Partida Italiana. El alfil va a c4 para atacar la debilidad de f7. Las negras juegan …Bc5 (Giuoco Piano) o …Nf6 (Dos Caballos)",
  "루이 로페즈(스패니시). 흑 c6 나이트를 압박해 e5 폰 수비를 흔듦. 가장 깊이 연구된 오프닝 중 하나": "Apertura Española (Ruy López). Presiona el caballo de c6 de las negras para sacudir la defensa del peón de e5. Una de las aperturas más estudiadas",
  "시칠리안 디펜스. 비대칭 구조로 반격. 최상위에서 가장 인기 있는 e4 대응": "Defensa Siciliana. Contraataca con una estructura asimétrica. La respuesta más popular a e4 en el máximo nivel",
  "님조/퀸즈 인디언 계열 입구. 흑이 유연하게 중앙 통제": "La entrada a la familia Nimzo/India de Dama. Las negras controlan el centro con flexibilidad",
  "{0} 정석 이론대로 전개되는 라인": "Una línea que sigue la teoría estándar de {0}",
  "2...f6는 f7-킹 대각선을 약화시키고 나이트 출구를 막는 대표적인 악수. 백은 e5 폰을 희생해 바로 응징 가능": "2...f6 es una jugada mala típica que debilita la diagonal f7–rey y bloquea la salida del caballo. Las blancas pueden castigarla de inmediato sacrificando el peón de e5",
  "3.Nxe5! 나이트를 내주고 폰을 잡으며 f7-h5 대각선 공략": "¡3.Nxe5! Entrega el caballo para capturar el peón y ataca por la diagonal f7–h5",
  "3...fxe5 받으면(거의 강제) e8-h5 대각선이 완전히 열림": "Si se toma con 3...fxe5 (casi forzado), la diagonal e8–h5 queda totalmente abierta",
  "4.Qh5+ 더블 어택. 4...Ke7 5.Qxe5+로 룩까지 따내며 백 대승": "4.Qh5+ es un doble ataque. Tras 4...Ke7 5.Qxe5+ las blancas ganan incluso la torre y obtienen una gran victoria",
  "5...Nxd5?는 폰을 되찾지만 f7이 무방비. 백은 나이트를 희생하는 프라이드 리버로 응징": "5...Nxd5? recupera el peón pero deja f7 sin defensa. Las blancas lo castigan con el Hígado Frito, sacrificando un caballo",
  "6.Nxf7! 나이트를 희생해 킹을 끌어냄": "¡6.Nxf7! Sacrifica el caballo para sacar al rey",
  "6...Kxf7 받으면 킹이 노출": "Si se toma con 6...Kxf7, el rey queda expuesto",
  "7.Qf3+ 킹과 d5 나이트를 동시에 공격. 백이 주도권": "7.Qf3+ ataca a la vez al rey y al caballo de d5. Las blancas tienen la iniciativa",
