  "불러오기": "Cargar",
  "PGN은 검증 후 그 수순 그대로 분석 탭에서 이어 둘 수 있음. FEN은 그 포지션(차례·캐슬링 권리·앙파상 포함)부터 이어 두는 FEN 모드로 전환되고, 처음 두는 수가 1수로 표기됨": "Un PGN se verifica y luego puedes continuar con esas jugadas en la pestaña Análisis. Un FEN pasa al modo FEN, que continúa desde esa posición (con el turno, los derechos de enroque y la captura al paso), y tu primera jugada se numera como 1",
