  "Tip: \"12.Nf3\"처럼 수 번호와 함께 적으면 해당 수로 이동하는 링크가 됨. 이어지는 수순으로 링크하려면 {0}처럼 대괄호 두 개 안에 수 번호와 수순을 공백으로 구분해 적기. 대괄호 안은 150자 제한에서 제외": "Consejo: si escribes una jugada con su número, como «12.Nf3», se convierte en un enlace a esa jugada. Para enlazar una secuencia, pon el número y las jugadas entre dobles corchetes separados por espacios, como {0}. El texto entre corchetes no cuenta para el límite de 150 caracteres",
