  "나이트로 목표 칸(★) 도달. {0}로 도착한 쪽이 라운드 승리, 같으면 {1} 도착한 쪽. 둘 다 못 가면 {2}, 거리도 같으면 {3} 승리. 제한시간은 10초에서 라운드마다 +2.5초, 7전 4선승": "Llega a la casilla objetivo (★) con tu caballo. Gana la ronda quien llegue en {0}; si hay empate, quien llegue {1}. Si ninguno llega, gana {2}, y si la distancia empata, gana {3}. El límite de tiempo empieza en 10 segundos y aumenta 2,5 segundos por ronda; gana quien llegue a 4 victorias de 7",
