  "1·2라운드는 방해 기물 없음. {0}, 라운드마다 증가. 상대 기물 칸에 도달하면 그 기물을 잡음. 상대가 지배하는 칸에 들어가면 내 나이트가 잡혀 라운드 종료. 공격선은 실제 체스처럼 다른 기물에 막힘": "Las rondas 1 y 2 no tienen piezas de obstáculo. {0}, y aumentan en cada ronda. Llegar a la casilla de una pieza rival la captura. Entrar en una casilla controlada por el rival hace que capturen tu caballo y termina la ronda. Las líneas de ataque quedan bloqueadas por otras piezas, como en el ajedrez real",
