  "짧은 메이트일수록 좋은 등급. {0}이 좋은 등급을 받을 확률이 높음": "Cuanto más corto el mate, mejor la calificación. Las probabilidades de una buena calificación son mayores para {0}",
  "퍼즐 레이팅이 낮은 쪽": "quien tenga menor rating de puzles",
  "동점이면 긴 메이트(4수 이상 → 3수 → 2수 → 1수) 성공 수부터 비교, 그래도 같으면 레이팅이 높은 쪽 승리": "En caso de empate se comparan primero los éxitos en mates más largos (4+ → 3 → 2 → 1); si sigue igual, gana el de mayor rating",
