  "실수율": "Tasa de errores",
  "아직 두 판 이상에서 반복된 실수가 없음": "Aún no hay errores repetidos en dos o más partidas",
  "이 실수를 모두 없애면 평균 정확도 최대 약 +{0}%p": "Eliminar todos estos errores podría subir la precisión media hasta unos +{0}%p",
