  "최근 {0}판 기준 변화": "Cambio en las últimas {0} partidas",
  "캐슬링": "Enroque",
  "평균 손실": "Pérdida media",
  "평균 정확도": "Precisión media",
  "표본 부족": "Pocos datos",
  "횟수": "Veces",
  "학습 탭은 내 성장을 모아 둔 곳입니다.": "La pestaña Aprender reúne tu progreso.",
  "내 대국을 5판 이상 리뷰하면 열립니다. 모자랄 때는 게이지 바로 남은 판 수를 알려 줍니다.": "Se abre cuando revisas 5 partidas tuyas o más. Mientras tanto, una barra de progreso muestra cuántas faltan.",
  "대국마다 오프닝, 전적, 탁월한 수와 유일한 수의 개수가 보입니다. 연두색 버튼으로 바로 리뷰할 수 있습니다.": "Cada partida muestra su apertura, el historial y la cantidad de jugadas Brillante y Única jugada. El botón verde la revisa al instante.",
  "레슨은 갈래를 따라 순서대로 열리고, 오프닝 원칙부터 시작합니다.": "Las lecciones se desbloquean en orden siguiendo las ramas, empezando por los principios de apertura.",
  "리뷰한 대국이 {0}판 이상이면 성장 분석이 열림": "El análisis de crecimiento se abre al revisar {0} partidas o más",
  "{0}판 더 리뷰하면 열림": "Revisa {0} partidas más para abrir",
  "최근 대국의 연두색 리뷰 버튼으로 내 대국을 리뷰하면 한 판씩 쌓임": "Al revisar tus partidas con el botón verde de revisión en Partidas recientes, se suman una a una",
  "분석한 실수": "Errores analizados",
  "백 1.e4 선택": "Juega 1.e4 con blancas",
  "백 1.d4 선택": "Juega 1.d4 con blancas",
  "백 측면 오프닝(1.c4·1.Nf3 등)": "Aperturas de flanco con blancas (1.c4, 1.Nf3, etc.)",
  "1.e4에 …e5 응수": "Responde a 1.e4 con …e5",
  "1.e4에 …c5(시실리안) 응수": "Responde a 1.e4 con …c5 (Siciliana)",
  "1.d4에 …d5 응수": "Responde a 1.d4 con …d5",
  "1.d4에 …Nf6 응수": "Responde a 1.d4 con …Nf6",
  "퀸사이드 캐슬링(캐슬링한 대국 중)": "Enroque al lado de la Dama (entre partidas con enroque)",
  "기물을 잡는 수의 비율": "Proporción de jugadas que capturan una pieza",
  "체크를 거는 수의 비율": "Proporción de jugadas que dan jaque",
