  "오프닝 선택": "Elección de apertura",
  "중반 성향": "Tendencias del medio juego",
  "대국 흐름": "Desarrollo de la partida",
  "약 {0}수": "~{0} jugadas",
  "거의 같음": "Casi igual",
  "비슷함": "Parecido",
  "다름": "Distinto",
  "많이 다름": "Muy distinto",
  "비교 불가": "No comparable",
  "차이": "Diferencia",
  "판정 기준 — 비율 기준(오프닝 선택·캐슬링·퀸 교환·무승부)은 %p 차이로 {0}%p 이하 거의 같음, {1}%p 이하 비슷함, {2}%p 이하 다름, 그 이상 많이 다름. 빈도·길이 기준은 두 값의 배수로 판정하며 체크·기물 잡기는 {3}배, 대국 길이는 {4}배 이하면 거의 같음. 실력 비교가 아님": "Cómo se fijan los niveles: en los criterios de proporción (elección de apertura, enroque, cambios de damas, tablas) decide la diferencia en puntos porcentuales — hasta {0} p.p. casi igual, hasta {1} p.p. parecido, hasta {2} p.p. distinto y más, muy distinto. Los criterios de frecuencia y duración usan el cociente de los dos valores: hasta {3}× en jaques y capturas de pieza y hasta {4}× en la duración de la partida cuenta como casi igual. No es una comparación de nivel de juego",
  "마스터 이름으로 검색": "Buscar maestros por nombre",
  "와(과) 기준별 비교": "Comparado contigo, por criterio",
  "일치도 {0}%": "Coincidencia {0}%",
  "학습 탭에 '성장 분석' 추가했습니다. 내 실수를 모아 보여 주는 약점 지도, 틀린 포지션을 간격을 두고 다시 푸는 복습 카드, 나와 닮은 마스터를 13가지 기준으로 비교하는 마스터 스타일 추가했습니다. 마스터 이름을 검색해 원하는 마스터와도 비교 추가했습니다.": "Se añadió «Análisis de crecimiento» a la pestaña Aprender: un mapa de debilidades con tus errores, tarjetas de repaso que traen de vuelta las posiciones que fallaste a intervalos espaciados y Estilo de maestro, que te compara con maestros en 13 criterios. Busca a cualquier maestro por nombre para compararte también con él.",
  "게임 리뷰 공유에 '하이라이트 카드' 추가했습니다. 한 판에서 가장 극적인 수 3개를 보드 그림과 승률 흐름으로 한 장에 담습니다.": "Se añadió una «tarjeta de destacados» al compartir revisiones: las 3 jugadas más dramáticas de una partida en una sola imagen, con tableros y la evolución de la probabilidad de victoria.",
  "도감 오프닝 트리·마스터 트리와 퍼즐 모식도에 전체 화면 보기 추가했습니다. 왼쪽 위 버튼으로 켜고 끔 추가했습니다.": "Se añadió la vista a pantalla completa al árbol de Aperturas, al árbol de Maestros y al esquema de problemas. Se activa con el botón de arriba a la izquierda.",
  "스마트폰 뒤로가기 지원합니다. 화면을 한 단계씩 닫고 홈에서는 한 번 더 누르면 종료했습니다. 앱에서 외부 링크는 시스템 브라우저·메일 앱·외부 사이트 앱으로 열기 추가했습니다.": "Se añadió compatibilidad con el botón Atrás de smartphone: cierra las pantallas paso a paso y, en Inicio, una segunda pulsación sale. En la app, los enlaces externos se abren en el navegador del sistema, la app de correo o la app de sitio externo.",
  "계정 및 데이터 삭제 안내 페이지(/account-deletion) 추가했습니다. 탈퇴하면 진행 중이던 대국은 기권 처리되고 내가 만든 퍼즐도 함께 삭제했습니다.": "Se añadió una página de eliminación de cuenta y datos (/account-deletion). Al eliminar tu cuenta, las partidas en curso se abandonan y los problemas que creaste también se eliminan.",
  "분석 탭 보드 위 버튼을 복사, 편집, 리뷰 순서로 정리하고 편집 버튼에 글자 추가했습니다. FEN/PGN 붙여넣기는 보드 편집 화면의 '불러오기'로 통합했습니다.": "Se reordenaron los botones sobre el tablero de Análisis a Copiar, Editar, Revisar y se añadió texto al botón Editar. Pegar FEN/PGN pasó a «Cargar» en la pantalla de edición del tablero.",
  "보드 편집 화면을 새로 디자인했습니다. 보드 중심 배치, 도구·기물·차례·불러오기·FEN 카드 추가했습니다.": "Se rediseñó la pantalla de edición del tablero: disposición centrada en el tablero con tarjetas de herramientas, piezas, turno, carga y FEN.",
  "도감 마스터 이름을 모든 언어에서 영어로 통일했습니다.": "Los nombres de maestros del Libro ahora se muestran en inglés en todos los idiomas.",
  "체크메이트 뒤 상대가 나가 끝나지 않은 대국이 새 매칭을 막던 문제를 수정했습니다. 결과 확정 요청이 실패하면 다시 시도 추가했습니다.": "Se corrigieron las partidas terminadas que no se cerraban tras un jaque mate porque el rival se fue y bloqueaban nuevas emparejamientos. La confirmación del resultado ahora se reintenta si falla.",
  "탈퇴한 계정이 만든 퍼즐에 작성자 아이디가 남던 문제를 수정했습니다.": "Se corrigió que el nombre del creador quedara en los problemas de una cuenta eliminada.",
  "좁은 화면에서 프로필 카드 위쪽 아이디가 버튼과 겹치던 문제를 수정했습니다. 통계 토글은 왼쪽, 프로필 편집은 오른쪽 정렬했습니다.": "Se corrigió que el nombre de usuario de la parte superior de la tarjeta de perfil se solapara con los botones en pantallas estrechas. El selector de estadísticas queda a la izquierda y Editar perfil a la derecha.",
  "성장 분석, 하이라이트 카드, 모식도 전체 화면, 스마트폰 뒤로가기, 계정 삭제 정리했습니다.": "Análisis de crecimiento, Tarjeta de destacados, Esquemas a pantalla completa, Botón Atrás de smartphone, Limpieza al eliminar cuenta.",
  "성장 분석, 하이라이트 카드, 모식도 전체 화면, 계정 삭제 안내합니다.": "Análisis de crecimiento, Tarjeta de destacados, Esquemas a pantalla completa, Guía de eliminación de cuenta",
  "성장 분석, 하이라이트 카드, 모식도 전체 화면, 계정 삭제 안내": "Análisis de crecimiento, Tarjeta de destacados, Esquemas a pantalla completa, Guía de eliminación de cuenta",
  "±{0}%p": "±{0} p.p.",
