  "{0}에 있는 {1:을/를} 잃게 됩니다.": "{1} en {0} en riesgo de perderse",
  "{0}의 {1:을/를} 이대로 두면 잃게 됩니다.": "{1} en {0} se pierde si se deja",
  "지금대로면 {0}에 있는 {1:을/를} 잃습니다.": "A punto de perder {1} en {0}",
  "{0}에 있는 {1:이/가} 당장 위험하지만, 엔진에 의하면 문제없는 수입니다.": "{1} en {0} expuesto, pero el motor valora bien la jugada",
  "{0}의 {1:이/가} 위험을 안고 있지만, 엔진에 의하면 괜찮은 수입니다.": "Deja {1} en {0} en riesgo, pero el motor lo aprueba",
  "{0}의 {1:을/를} 잃을 수 있어도, 엔진에 의하면 좋은 수입니다.": "{1} en {0} podría perderse, pero el motor la valora bien",
  "이 수는 상대 {0:을/를} 위협합니다.": "Amenaza a {0} rival",
  "상대 {0:이/가} 이 수의 위협을 받고 있습니다.": "Amenaza, {0} rival bajo ataque",
  "이제 상대 {0:을/를} 위협하고 있습니다.": "Esta jugada crea una amenaza a {0} rival",
  "상대 {0:이/가} 걸려 있습니다. 잡을 기회입니다.": "Ocasión de capturar, {0} rival expuesto",
  "상대 {0:을/를} 잡을 수 있는 상황입니다.": "Se puede capturar {0} rival",
  "아직 상대 {0:이/가} 방치돼 있습니다. 놓치지 말아야 합니다.": "No lo pases por alto, {0} rival sin protección",
  "{0:을/를} 잡지 않았지만 여전히 좋은 수입니다.": "No capturó {0}, pero es buena jugada",
  "{0:을/를} 잡을 수도 있었지만, 이 수도 충분히 좋습니다.": "Podía capturar {0}, pero esta jugada también basta",
