  "유리한 상황이라도 목적 없는 기물 교환은 손해가 될 수 있습니다. 기물 교환은 목적을 갖고 해야 합니다.": "Aunque vayas ganando, cambiar Piezas sin un propósito puede salir caro, cambia Piezas con un objetivo.",
